insert into program_modules (key, order_no, title, description, source_doc) values ('key_2', 3, 'Key 2 — Finally Free''s "Virtual Detox" Program: "The 21"', 'Finally Free''s "Virtual Detox" Program- "The 21" 10-26 Foundational program "Key #2" (Review this every 6-12 months to stay accountable and keep healthy! "The back to basics approach")
insert into program_modules (key, order_no, title, description, source_doc) values ('key_3_part_1', 4, 'Key 3 — Bill''s Story, Part 1 (minutes 1–59)', 'Bills story worksheet 1 to 59 minutes
