insert into program_modules (key, order_no, title, description, source_doc) values ('certification', 6, 'Certification', 'Your certification packet is assembled from your Key 1 worksheet, Key 2 cover sheet and orange turn-ins, and Key 3 Parts 1 and 2. A leader reviews and approves it.', null);
