insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 1, 1, 'Pray morning and night', 'Pray in the Morning: ask God for just this 1 day of sobriety, to save you from the insanity, and then Thank him at night for getting you through the day (you didn''t do it!)
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 2, 2, 'Pray 30 days to be a fisher of men', 'Pray for 30 days. Pray for God to use You, to be fisher of men, worker of the harvest, etc.
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 3, 3, 'Clear home of porn and triggering material', 'Clear Home of all Porn and suggestive triggering material, (Get family to help if its ok)', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 4, 4, 'Get daily resources', 'Get daily Resources: (A)- Request and Join FF Signal Groups, (B)-Get nextmeeting for FF - "Finallyfreeapp.com," (C)-Get SA nextmeeting app, (D) Has Zoom link from flyer or FF app, and successfully entered meeting rooms for FF. (I get an email that shows youve done this.) (Know ahead of time how to get into our meetings). "IF" you dont have any of these, simply ask another member to give it to you.. :)', false, 'triple', false, null, '{"type": "meeting_link_joined", "sub": "D"}'::jsonb);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 5, 5, 'Save 20+ member contacts', 'Download all members'' Phone numbers OR International Signal phone numbers to your Phone as a personal contact. Make a minimum of 20 member "CONTACTS" on your phone. (A MUST).', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 6, 6, 'Install accountability software', 'Install accountability software on ALL devices, (ask who on signal is a "Software Admin"). Covenant eyes allows for up to 10 users on 1 account. Pay $20 a year instead of $200 a year through one of our admins. We always have a group rate that is a fraction of regular cost. Make sure you also have at least 3 "allies" on your accounts that are regularly getting your reports.', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 7, 7, 'Do your disclosure', 'Sign up and get on calendar now and DO YOUR DISCLOSURE in the Friday Night DISCLOSURE MEETING asap!! (The truth will set you free! John 8:32)', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 8, 8, 'Buy the AA Big Book and 12 x 12', 'Buy AA Bigbook and AA 12 x 12, Used is $5-10 each, Ebay / Amazon.', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 9, 9, 'Write Steps 1, 2 and 3', 'This is the "Fire Extinguisher" for your Addiction! Go Online, google Alcoholics Anonymous 12 steps and 12 traditions pdf. Download. Read steps 1,2,3 and write a page for each step. (You will go over these with your AP partner, and them, you. This is Crucial for stability/sobriety now! You will stress and struggle until you implement this!) STEPS 1, 2,AND 3, GET YOU SOBER!!------------ DO STEPS 1,2, AND 3!! TURN IN****', true, 'triple', true, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 10, 10, '90 in 90 sheet and home group', 'Get and PRINT OUT your 90 in 90 sheet, Begin to attend and document your "90 meetings in 90 days", ONLY "Finally Free" and "SA" support meetings count. Look for and decide who your "HOME GROUP" is going to be. Many people relapse by never committing to a group. (A home group is your "Tribe" -your family in recovery). We hope after you have watched the first 3 videos and understand what we stand for and our mission, as well as the greater prospects for permanent sobriety, you will remain and align with us.
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 11, 11, '"My Program" page', 'Has blank page titled "My Program". Begin to catalog things heard in meetings, read, etc, that you want to write down and implement to help you in your program to stay sober. (Attach your 21 to this; it is THE BEST "BASE" for your program)!!!
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 12, 12, 'Commit to a service position', 'MANDATORY!! WITHIN 14 DAYS of joining us, YOU MUST Commit to a service position and implement it. If none available, you must find a need, be creative, get it approved, and apply it (everyone serves period!). There are lots of opportunity in OUR Ministry and Meetings, just ask!!! Doing something early on or just a few times is not being in service, it WAS in service. Find something ongoing you can be involved with. IF YOU DON''T WANT TO SERVE, YOU DONT BELONG IN MINISTRY.
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 13, 13, 'Time commitment statement', 'Time commitment statement (Prioritizing your program, completing the 3 Keys, and all the exercises, phone calls, meetings, and activities come first in your life). How will you do it? Read to the group. (God made a way where there was no way, and parted the red sea; He can make time and resources all work for you if you trust and lean on Him).
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 14, 14, 'How I will help others', 'How you will begin to help others now in the short term? How will you help others in the long term? Tell the story!! Read to group. (Think wonderfully big, even the scary things) TURN IN ********', true, 'triple', true, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 15, 15, 'How I will help my accountability partner', 'Write out and present to group "how you are going to help your accountability partner get and stay sober." TURN IN ************', true, 'triple', true, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 16, 16, 'Get an accountability partner', 'Obtain an account partner and talk daily. Look for life and death seriousness, responsibility and similar in age if possible. Have them go over their 21 and read to you, also their 3 pages: Items 14, 15, 16. How they are going to help YOU stay sober? Look for their level of commitment, management and prioritization of time, and mostly, their willingness to help others, before you choose them. AP:', false, 'triple', false, null, '{"type": "relationship", "rel": "ap", "background": true}'::jsonb);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 17, 17, 'Night Battle box breathing', 'Research and do Night Battle box breathing from conquerors episode 2.', false, 'triple', false, null, null);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 18, 18, 'Have a sponsor or temporary sponsor', 'Has A sponsor or "Temporary Sponsor" BY COMPLETION OF 90 DAYS. Look for, preferably a FF sponsor that has completed their 3 keys and has at least 12 months of sobriety, if possible. If they are a mentor or / SA" sponsor, and they are aware of your participation in FINALLY FREE, make sure they willing to cooperate/work with OUR curriculum. Ask them if they are willing to learn our "3 keys to Freedom" to go over it with you (the problem often is, they will prioritize "working steps" OVER serving God now).
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 19, 19, 'Sponsor someone', 'Within 30 days, you have reached out and found someone that YOU are Sponsoring and are working with "intensely" (Not Passively) to help them get free by teaching them everything you have learned, especially the "3 Keys to Freedom". This is, perhaps, the most important step of all curriculums and programs, and "proves" we are doing all the other things by doing "This". Name / Group:', false, 'triple', false, 30, '{"type": "mentee_linked", "background": true}'::jsonb);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 20, 20, 'AP reviews your 21 (cover sheet)', 'Have accountability partner go over all your 21 diligently with you, looking for holes or weak areas and solidify your understanding and application of all of these steps and help you complete them. Then, you will likewise, critique his 21 too. He will initial the second column of the cover sheet to be turned in. Upload all "orange" work.', false, 'triple', false, null, '{"type": "cover_sheet"}'::jsonb);
insert into program_steps (module_id, order_no, item_number, title, description, turn_in, gate_type, requires_upload, due_day, helper) values ((select id from program_modules where key = 'key_2'), 21, 21, 'Give hugs', 'Give hugs!! This is the HEALING STEP if you will commit to it!! Sexual addiction is a panic of not being loved and not being soothed or comforted. Feeling not good enough to be loved or validated, we fearfully demand these feeling be fulfilled in sex. If addiction is synthetic, we must realize that we are REALLY actually desiring to be loved! God''s Word says PERFECT LOVE casts out fear, 1 John 4:18. If we want to get to the heart of this lust, we must do the opposite of what we think and feel! Read St Francis prayer and his conclusions. Begin to find "SAFE PEOPLE" TO "COMFORT" daily. Your wife, kids, friends, co-workers, etc. Become the comforter of others! Set goals for "Free hugs" given, and learn to listen and empathize with others. Become that friend that YOU need. Giving Gods perfect love to others will powerfully retrain your mind out of panic mode when we die to ourselves and choose to love others. ** Pray first; make sure lust is not in your heart when you reach out. If unsure how to begin, talk to others.', false, 'triple', false, null, null);
insert into app_settings values ('key2_closing', '"Congratulations, You have 1 Key left before certification. Watch the Bills movie and do the questionnaire. Remember \"Do the 21 and your addiction is done!\" ;)"'::jsonb) on conflict (key) do update set value = excluded.value;
