insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 1, null, 'take a ways: what really stands out to you in the first section of the movie about his alcoholism until the time he is admitted into the hospital for the last time at minute 59.00 ( do not take notes in this section beyond this part of the movie).', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 2, null, '1) How do you relate his alcoholism to your sex addiction for such items as progression, justification obsession and ?? 2) Do you see the parallel?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 3, '@2', '"We were to talk for 15 minutes, we spoke for 6 hours"...connection of 2 addicts, Are you experiencing that here yet???', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 4, null, '"We brought a lot of people with us". 1) What if that was possible for us as a group to save and rescue many a lives, would that be of interest to you? 2) Would you allow God to do this with your life?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 5, null, '"How much our lives have changed, just because we don''t drink no matter what!!" 1) No matter what, do you suppose life will get better for us too, if we just don''t act out??? 2) Why is it dangerous to think that we need to solve internal issues before we get sober?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 6, '@3', '1) How does Keep it simple" help us stay focused on God and service if we allow it? 2) How do we become ineffective for the Kingdom when we get caught up in the Grind and Grouch with others? Compare to John 9:4.', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 7, null, '15 years later, 100k people recovered, in just 15 years!! 1935-50. (1950 Dr Bob died)', 0);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 8, '@4', 'Bill driving with Lois says, " Smitty''s always been my anchor, and now he wont be around." Do we allow ourselves to feel deeply that way about anything or anybody except the addiction?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 9, null, 'Movie starts 1919, then 1935 AA starts, only 16 years He''s a complete mess...', 0);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 10, '@5', 'Youthful ambition, success in the army, going to conquer the world for ourselves, walking with duffle bag and Lois, I was a good leader, nothing he felt he couldn''t do.... 1) Can you relate? Many a young man, skips off recovery today because they "Think" they know and have it all together.. 2) Is this you??? See aa 12x12 chapter 2..', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 11, '@11', 'Wife home pregnant, hes still drinking hours later not wanting to leave the party, and now with girl on arm, why not, it feels great. No inhibitions of morals to get in the way... Relate???', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 12, '@14', 'At hysterectomy, its all about him, not her, Ever done this??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 13, null, 'People suffered in our lives because we were not there for them. Are you beginning to see this? (You will more and more as you sober)', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 14, '@19', 'In tent, radios that can reach Canada, moving talking pictures, electric appliances. In the 30s.. Bill says after factory tour, "we are on our way." 1) Does personal success feel good? 2) What are the dangers?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 15, null, '1) What is Bills philosophy? Drive in life? 2) Who is he serving? Who is it for? 3) What does Ecclesiastes call this? ( Repeated theme over and over in the book of Ecclesiastes.). 4) Does not every human being repeat this same mistake today? 5) Is then Bills story really that unique than anyone of us today?', 5);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 16, '@21', 'At Dinner with family (spilling wine), tries to "Normalize" his drinking seeking acceptance. Tell of a time or two, you sought acceptance from others for your sexual addiction trying to "Normalize it."', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 17, '@23', 'At Dr''s - States he made half a million in 2 years, in the 30s! Wow, and a radio in every room!! The denial, "its what makes life work, its part of his business!!." Relate to the its my cure-all feeling about this addiction?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 18, '@24', '1) What effect does Bill find out that his liver being enlarged have on his drinking? 2) Can we remember a time when emminent danger lurked for us in our addiction and we grossly minimized reality so we could enjoy it without worry?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 19, '@26', 'its not booze, just wine!! justification... Relate, how do we do this justification and minimizing with this addiction??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 20, '@27', 'The demoralization of the wine seller, just chasing fun, feeling good, no consequences, no alarms, judgment is gone. Ever felt that with this addiction..?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 21, '@30', 'Lois says, "its not just the drinking, its common decency",,, did your morals become more lose and inconsiderate in your addiction??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 22, null, 'Talking about 1929, what happens in 1929....?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 23, '@34', '1931, sipping booze while in car ( going into live with father in law); is his cure all, no question no fight.. He''s chronic. His ability to function is greatly diminished, non existent. Tell us about how this was becoming true for you.', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 24, '@39', 'Hes so bad, Frank wants to give him a few bucks just to get rid of him..', 0);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 25, '@41', '1) Compare the "theory''s of 1930s alcoholism " to today''s view on sex addiction with society. 2) Do we in fact still have a long way to go as far as understanding of this disease?? 3) Why do you suppose they put the "Dr''s Opinion" in front of "The key persons" or rather Bills story being first in the book titled Alcoholics Anonymous?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 26, '@43', 'He was on top of the world, but now says never felt the same, never measured up, always felt alone, gave him courage, never felt security, helped to dream, but said nothing was enough. Wanting to feel alive inside... full of more fear.. guilt, depression, yet would give all just for another drink.. 1) Do you relate to this "Insanity?" 2) What program steps are a must?? 3) 3) He talks about Connection, but has his been real or synthetic? 4) Can you see why someone who is addicted would feel "not apart of people or the world and alone all the time?"', 4);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 27, '@44', 'he talks about feeling whole from having that first drink overseas, How did sexual acting out make you feel?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 28, '@42-46', 'While this is not his last run, 1)what is he doing that is beginning his journey to freedom? 2) Have you done this yet? There is a specific tool in place in our group to help you with this, that you must do! ( to be discussed during meeting if you didn''t get it).', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 29, '@48', 'the tour of the hospital, 1) If we really KNEW that this was our future dismal outcome, would we be much more serious now about a prescribed recovery plan? 2) What Might help us realize this truth for ourselves and motivate us?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 30, '@52', 'Ebby, 4 + months sober, then goes sees Bill, Bill is dying, and still he''s defensive against letting it go!!', 0);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 31, '@52', 'according to Ebby, 1) who was the predecessor group of AA? 2) What 3 things did he say their program asked them to do? 3) How is this seemingly different than from much of 12 steps of today?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 32, '@52', 'See how quickly his anger, and justification turns against religion and possible help, his emotions and thinking is barbaric. 1) Did anyone tell you that you needed help with this before? 2) What if they did, how would you have felt?? defensive or open??', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 33, '@54', 'Ebby says, if ever needs to talk, its not necessarily about drinking anymore, but about their relationship. Do you see the huge spiritual separation between the 2 now?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_1'), 34, '@57', '1) What things did Lois say that Bill had deprived her from? 2) How did she cope with this? 3) How have we noticed our loved ones and children coping with our inability to be there for them in our addiction?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 1, null, 'As he has his "spiritual experience at minute 59, and then begins to rescue others, what mistakes were made from this part of his life? (Minute 59 to 119.) Pay close attention to dialogue..', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 2, null, 'What were the keys that DID get Dr Bob and AA # 3 (The first guy in the hospital) sober, What things can we also personally relate to if someone was approaching you and you were sick?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 3, null, 'What were some of the other important take a ways from the movie you related to? 1) How about Bills attitude and exchanges with Lois? 2) How do you relate these? 3) Why was Bills attitude towards all this so necessary?? 4) Are you developing these same attitudes?? explain.', 4);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 4, null, 'Why was Bill and Bob so adamant about finding a solution to their addiction?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 5, null, 'As you learn more and study the history of these men, did their "fruits'' surpass that of what we see in modern recovery resources today?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 6, null, 'Why do you suppose this is??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 7, null, 'Why do you think the component of denial in addiction is so powerful in the individual even when all outside observers can see the severity of the problem??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 8, null, 'even though you and are are not brain dr''s, can you see how a habit" such as addiction can become over powering to the afflicted brain and body? explain.', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 9, null, 'Can you think of a biblical verses that discusses dealing with this "stronghold?" see also Mark 3:25', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 10, '@102', 'What is the first think he was told he must do when he got out of the hospital???', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 11, '@103', '1) How much time did Bill seem to be putting into "giving it aways to others" (also see @105). 2) Who was Bills greatest success up to this point?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 12, '@103', 'even though he was getting the men fresh out of the hospital ( exhibiting the depth of their sickness), 1) how serious were these men to changing their lives? 2) How foolish, unmotivated and blind do you see yourself? 3) What is different this time?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 13, '@104', 'No one was quitting, yet he was hopeful for the new one he had just brought home. 1) Why? 2) Why is this Necessary to get sober? 3) Is this you?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 14, '@104', 'Sees Lois in bed, he comments, "you keep giving and I keep taking." Why is him making this statement a very good thing?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 15, null, 'The guy in the kitchen kills himself... (see AA book).', 0);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 16, '@105', 'The people in Bills house, - 1) who was able to get sober? 2) Was it a success?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 17, '@106', 'Why do you suppose Bill was so angry going to Akron, for a new business venture?? disappointed, like his heart wasn''t right??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 18, '@108', 'Could you feel Bills boredom / loneliness in the hotel lobby??? Did a best friend seem to be calling him from the bar?? Have you ever felt this best friend calling you from loneliness??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 19, '@110', 'Bill was obviously temped as he continued to look into the bar, 1) He realized that in order to save himself he must do what? 2) What do you tend to do when you are tempted to act out? 3) Does your mind think like Bill? 4) Why or why not?? 5) Why was Bills previous 6 months of "failure" now so important to him overcoming temptation on this trip?', 5);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 20, null, '1) Do you think Bills experiences as a stockbroker and sales man, aided him as he began pulling men off the street and also canvassing for men to help on the phone? 2) What talents and experiences can you be using to help rescue men for God?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 21, '@114', 'While Bills comment almost seems rude, "I didn''t come to help you, I came to help myself." 1) How does this simple statement solidify the purest message of recovery. 2) Is this the same message that we receive now???', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 22, '@111', '1) what program steps did Bill work to get sober? 2) What steps did he work in the 5 previous months? 3) How is this different from today?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 23, null, '1) What steps should we work before we are ready to reach out to others and do Gods work?? 2) What veres draw you to this conclusion?', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 24, null, 'At first, those 2 men seemed to be inseparable. 1) What prior was each man inseparable from??? 2) Is there new life in fact better? 3) Is this a good example of intensively and strenuously working with others? 4) How about "bearing each others burden?" 5) How about discipling another???', 5);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 25, null, 'Lois reads letter, we have learned more in few weeks than we learned in whole time I was trying to shove religion down those poor drunks throats. 1) Can you see why a sick human would be resistant? 2) Why did it not work??? 3) What must we be careful of???', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 26, null, '1) What was wrong with Ebby?? 2) What 2 things would lead to his ultimate demise and real death?? 3) How serious was this personal mistake??', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 27, null, 'Does it help you to see the 12 step movement develop in front of your eyes and the simplicity there of? Why??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 28, null, 'Never occurred to bob, to help others as a way to stay off the stuff.. did it to you?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 29, null, 'Cryptic but poignant. "Buddies, on the stormy sea of booze, 1) How does that relate? 2) Why does it work and bond??', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 30, '@118', 'Start with guys that are ready that realize they have had enough, 1) Why is this important?? 2) How do you find out if this is true???', 2);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 31, '@120', 'APPROACH (AA #3): "we both had a problem... we couldn''t lick it ourselves.. we found we can do it together, how long sober??? See the hope the testimony in us???? Are you guys religious??? 1) Why is this so defensive, 2) Why such a turn off???? 3) Look deep inside for this answer... 4) Can you see yourself walking into this setting aand telling another that you are a sex addict, to help them and show that you have found a way out? YOU WILL!! very soon!!!', 4);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 32, '@122', 'What is the tie in to the BB? The story titled "AA number 3"', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 33, null, 'Why is it important to not push too hard early?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 34, null, 'What is the most important things to convey???', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 35, null, '1) Why did Ebby get drunk? He says you know what I need right now, 2) what did he mean??? 3) Why do you think this relapse was so bad?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 36, '@125', 'Bill tells Lois, says he thought drinking would go away, now knows will deal with this all of life, 1) Do we realize that this illness never goes away??? 2) Does this line up with Gods Word?? Why or Why not? Many groups are very torn about this. 3) Why is the "Purests" version of this, ( Completely healed), unrealistic for many? (Ref Paul and the "Thorn in the side for 1).', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 37, '@126', 'Tells Lois, He must stay sober by being with other drunks. Do you believe this is necessary for you to go to these extremes???', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 38, null, 'Seen Ebby, realized not drinking is most important thing of his life and care about. 1) Do we prioritize like this?? 2) Does God want us to prioritize the same?? Fleeing from sin?? 3) Without committing our lives to God and the service to Him, can we ever escape the pulls and as we''ve found, "The lusts of this world?"', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 39, '@127', 'Even though AA was anonymous, 1) Did they hide? Or tell their story? 2) What 2 things did they do in sections 130-140 to illustrate this?? 3) How does this TRUTH line up with Rev 12:11? 4) What promise is in this verse for us if we choose to listen and follow?', 4);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 40, null, 'Love how he says, Thanks for keeping me sober for one more day!!', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 41, '@126', 'note the incredible commitment Bill made, and the toll on their marriage. 1) Do you see why a couple needs to be of faith so they can agree to serve God and both be secure in that service in order to succeed? 2) What word describes what the wife must also do? 3) Who does each adult need to put first?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 42, '@130', 'Did the human side of Lois have the right to be jealous?', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 43, null, 'Sat evening post was a big boost for the new society, they had great acceptance from the world because homes and families reunited. 1) Could we do that too? 2) Whats holding us back??? 3) What was the new orgnization hoping to accomplish?', 3);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 44, null, 'Final scene, Bill is gentle of heart, open to serve God, to be there for others, he has the experience to help others, he understands!!! Lois understands and supports what hes doing for God, you all should be so lucky!! Only a Godly woman can give of herself this way, -being secure... How can we help our wives feel secure??', 1);
insert into worksheet_questions (module_id, order_no, timestamp_label, prompt, answer_slots) values ((select id from program_modules where key = 'key_3_part_2'), 45, null, 'The final scene is perfect I cried, I understand. You must experience this. Only God can help you fully surrender to this life. You must be so scared that you re-look at, reconsider everything. Are you afraid enough to change???', 1);
